const item = $input.first();

const binary = item.binary || {};

return Object.entries(binary).map(([key, file]) => {
  return {
    json: {
      file_name: file.fileName,
      mime_type: file.mimeType,
      binary_property: key
    },
    binary: {
      data: file
    }
  };
});

return {
  json: {
    cv_text: $json.text,
    file_name: $binary?.data?.fileName || "Unknown CV"
  },
  binary: $binary
};

return {
  json: {
    file_id: $json.id,
    file_name: $json.name || $json.originalFilename,
    cv_link: `https://drive.google.com/file/d/${$json.id}/view`
  },
  binary: $binary
};

return {
  json: {
    ...$json,
    cv_link: $('Code in JavaScript7').item.json.cv_link,
    file_name: $('Code in JavaScript7').item.json.file_name
