Candidate Information:

Name: {{ $json.output.candidate_name }}
Email: {{ $json.output.email }}
Phone: {{ $json.output.phone }}
Skills: {{ $json.output.skills }}
Education: {{ $json.output.education }}
Experience: {{ $json.output.experience_years }} years

Job Information:

Job Title: {{ $json.job_title }}
Required Skills: {{ $json.required_skills }}
Responsibilities: {{ $json.responsibilities }}

Evaluate this candidate ONLY against this specific job.

Consider:
1. Required skills match
2. Relevant experience
3. Technical relevance
4. Responsibilities alignment

Do not invent skills or experience that are not present in the candidate information.

Return ONLY valid JSON in this exact format:

{
  "score": 0,
  "status": "",
  "matching_skills": [],
  "missing_skills": [],
  "reason": ""
}

parameters.jsCode:
const candidateData = $('Code in JavaScript9').item.json;

const candidateSkills = String(
  candidateData.output?.skills || ""
);

const requiredSkills = String(
  candidateData.required_skills || ""
);

// Convert skills to arrays
const candidate = candidateSkills
  .split(",")
  .map(skill => skill.trim().toLowerCase())
  .filter(Boolean);

const required = requiredSkills
  .split(",")
  .map(skill => skill.trim().toLowerCase())
  .filter(Boolean);

// Normalize skill names
function normalizeSkill(skill) {
  let s = skill
    .toLowerCase()
    .trim()
    .replace(/\s+/g, "");

  const aliases = {
    "html5": "html",
    "css3": "css",
    "reactjs": "react",
    "react.js": "react",
    "nodejs": "node",
    "node.js": "node",
    "expressjs": "express",
    "express.js": "express",
    "restapi": "restapis",
    "restapi's": "restapis"
  };

  return aliases[s] || s;
}

// Matching
const matchingSkills = required.filter(requiredSkill => {
  const normalizedRequired = normalizeSkill(requiredSkill);

  return candidate.some(candidateSkill =>
    normalizeSkill(candidateSkill) === normalizedRequired
  );
});

// Missing
const missingSkills = required.filter(requiredSkill => {
  const normalizedRequired = normalizeSkill(requiredSkill);

  return !candidate.some(candidateSkill =>
    normalizeSkill(candidateSkill) === normalizedRequired
  );
});

return {
  json: {
    ...$json,

    matching_skills: matchingSkills,
    missing_skills: missingSkills
  }
};

const candidateData = $('Code in JavaScript9').item.json;
const result = $('Basic LLM Chain').item.json.output || {};

const matchingSkills = $json.matching_skills || [];
const missingSkills = $json.missing_skills || [];

const experienceYears = Number(
  candidateData.output?.experience_years || 0
);

const totalSkills =
  matchingSkills.length + missingSkills.length;

const skillScore =
  totalSkills > 0
    ? (matchingSkills.length / totalSkills) * 80
    : 0;

const experienceScore =
  Math.min(experienceYears / 3, 1) * 20;

const score = Math.round(
  skillScore + experienceScore
);

let status;

if (score >= 80) {
  status = "Highly Qualified";
} else if (score >= 60) {
  status = "Potential Candidate";
} else {
  status = "Rejected";
}

return {
  json: {
    "Test Case": "CV Screening",
    "job": candidateData.job_title || "",
    "Candidate": candidateData.output?.candidate_name || "",
    "Experience": experienceYears,
    "Email": candidateData.output?.email || "",
    "Email Status": "",
    "Phone": candidateData.output?.phone || "",
    "Education": candidateData.output?.education || "",
    "Score": score,
    "Matching Skills": matchingSkills.join(", "),
    "Missing Skills": missingSkills.join(", "),
    "AI Concerns": result.reason || "",
    "AI Recommendation": status,
    "HR Decision": "",
    "Original CV": candidateData.cv_link || "",
    "LinkedIn URL": candidateData.output?.linkedin || "",
    "Github URL": candidateData.output?.github || "",
    "Portfolio": "",
    "Interview Questions": "",
    "HR Notes": ""
  }
};

const items = $input.all();

const seen = new Set();
const uniqueItems = [];

for (const item of items) {
  const candidate = item.json;

  const key = [
    candidate.Candidate,
    candidate.Email,
    candidate.job
  ]
    .map(value => String(value || "").trim().toLowerCase())
    .join("|");

  if (seen.has(key)) {
    continue;
  }

  seen.add(key);
  uniqueItems.push(item);
}

return uniqueItems;

const candidates = $input.all().map(item => item.json);

const validCandidates = candidates
  .map(candidate => ({
    ...candidate,
    Score: Number(
      candidate.Score ??
      candidate.score ??
      0
    )
  }))
  .filter(candidate =>
    candidate.Candidate &&
    candidate.Score >= 60
  );

validCandidates.sort((a, b) => b.Score - a.Score);

const top3 = validCandidates.slice(0, 3);

return top3.map((candidate, index) => ({
  json: {
    ...candidate,
    Rank: index + 1
  }
}));

const candidates = $input.all().map(item => item.json);

let message = `Top Candidates for Hiring

Job: ${candidates[0]?.job || ""}

We reviewed the submitted CVs and selected the top qualified candidates:

`;

candidates.forEach((candidate, index) => {
  message += `
--------------------
Rank ${candidate.Rank || index + 1}

Candidate:
${candidate.Candidate || ""}

Score:
${candidate.Score || 0}/100

Experience:
${candidate.Experience || 0} years

Email:
${candidate.Email || ""}

Phone:
${candidate.Phone || ""}

Education:
${candidate.Education || ""}

Matching Skills:
${candidate["Matching Skills"] || "None"}

Missing Skills:
${candidate["Missing Skills"] || "None"}

AI Recommendation:
${candidate["AI Recommendation"] || ""}

AI Assessment:
${candidate["AI Concerns"] || ""}

LinkedIn:
${candidate["LinkedIn URL"] || "Not provided"}

GitHub:
${candidate["Github URL"] || "Not provided"}

CV:
${candidate["Original CV"] || "Not provided"}

`;
});

message += `
--------------------

Please review the candidates and make the final HR decision.

This shortlist was generated automatically by the CV Screening System.
`;

return [
  {
    json: {
      message: message,
      candidates_count: candidates.length,
      top_candidate: candidates[0]?.Candidate || ""
    }
  }
];

const candidate = $('If').item.json;

const questions = $json.output?.interview_questions || [];

return {
  json: {
    ...candidate,
    "Interview Questions": questions
      .map((q, index) => `${index + 1}. ${q}`)
      .join("\n")
  }
};

const body = $json.body;

const requiredFields = [
  "candidate",
  "email",
  "job",
  "date",
  "time"
];

const missingFields = requiredFields.filter(
  field => !body?.[field] || String(body[field]).trim() === ""
);

if (missingFields.length > 0) {
  return [
    {
      json: {
        success: false,
        error: "Missing required fields",
        missingFields
      }
    }
  ];
}

return [
  {
    json: {
      success: true,
      candidate: body.candidate.trim(),
      email: body.email.trim(),
      job: body.job.trim(),
      date: body.date,
      time: body.time
    }
  }
];

